data:
{
 "_comment": "The triage taxonomy. The triage skill, the block validator and the triage playbook all read this List: a type is valid for an incident only when its domain (detection or posture, decided by the incident route) is in `domains`; anything else goes to `other`. `sub_playbook` is the playbook the type branches to, `skill` the skill its investigation session loads. GuardianCommon's GUARDIAN_TRIAGE_DEFAULT_TYPES holds the same data and is used only when this List cannot be read; a content test keeps the two equal. Adding a type also needs a branch in GuardianTriageAndInvestigateIncident and a sub-playbook.",
 "severities": [
  "low",
  "medium",
  "high",
  "critical"
 ],
 "types": [
  {
   "name": "phishing",
   "description": "A reported or detected email: phishing, malicious attachment or link, business email compromise.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriagePhishing",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "identity_threat",
   "description": "Sign-in anomaly, credential use, brute force or session abuse by a person or service account.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageIdentityThreat",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "endpoint_threat",
   "description": "Malware, suspicious execution or persistence on a host.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageEndpointThreat",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "network_threat",
   "description": "Network detection: command and control, scanning, IDS/IPS or firewall alert, suspicious traffic.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageNetworkThreat",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "data_exposure",
   "description": "Data loss prevention alert, exfiltration, or public or over-shared data.",
   "domains": [
    "detection",
    "posture"
   ],
   "sub_playbook": "GuardianTriageDataExposure",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "vulnerability",
   "description": "A known CVE or scanner finding on a host, image or application.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageVulnerability",
   "skill": "xsoar_case_investigation"
  },
  {
   "name": "other",
   "description": "None of the above fits; an analyst decides.",
   "domains": [
    "detection",
    "posture"
   ],
   "sub_playbook": "GuardianTriageOther",
   "skill": ""
  }
 ]
}
